import jakarta.servlet.http.*; 
public class LogoutServlet extends HttpServlet { 
protected void doPost(HttpServletRequest request, HttpServletResponse response) 
throws ServletException, IOException { 
HttpSession session = request.getSession(false); 
String name = (String) session.getAttribute("name"); 
LocalDateTime startTime = (LocalDateTime) session.getAttribute("startTime"); 
LocalDateTime endTime = LocalDateTime.now(); 
Duration duration = Duration.between(startTime, endTime); 
long seconds = duration.getSeconds(); 
session.invalidate(); 
response.setContentType("text/html"); 
PrintWriter out = response.getWriter(); 
out.println("<html><head><title>Logout</title></head><body>"); 
out.println("<h1>Thank You, " + name + "!</h1>"); 
out.println("<p>You used the application for " + seconds + " seconds.</p>"); 
out.println("</body></html>"); 
} 
} 
